/**
 * Service Worker lifecycle management for the decrypt proxy.
 *
 * The SW intercepts /decrypt-stream/* URLs from media elements,
 * decrypts AES-CTR content, and returns proper HTTP responses.
 */

import { logger } from './logger';

/**
 * Register the decrypt Service Worker.
 * Returns the registration or null if SW is not supported.
 */
export async function registerDecryptSW(): Promise<ServiceWorkerRegistration | null> {
  if (!('serviceWorker' in navigator)) {
    logger.warn('[SW] Service Workers not supported in this browser');
    return null;
  }

  try {
    // In dev mode, Vite serves TS directly. In production, the SW
    // is compiled to /decrypt-sw.js via the Vite build config.
    const swUrl = import.meta.env.DEV ? '/src/workers/decrypt-sw.ts' : '/decrypt-sw.js';

    const registration = await navigator.serviceWorker.register(swUrl, {
      scope: '/',
    });

    // Wait for the SW to be ready to accept messages
    await navigator.serviceWorker.ready;
    return registration;
  } catch (err) {
    logger.error('[SW] Registration failed:', err);
    return null;
  }
}

/**
 * Send a message to the active Service Worker controller.
 */
export function sendToSW(message: unknown): void {
  navigator.serviceWorker.controller?.postMessage(message);
}

/**
 * Check whether a Service Worker controller is active.
 */
export function isSwActive(): boolean {
  return 'serviceWorker' in navigator && !!navigator.serviceWorker.controller;
}

/**
 * Wait for the SW controller to become available.
 * Resolves immediately if already active, otherwise waits for
 * the controllerchange event. Times out after 5 seconds.
 */
export function waitForSW(): Promise<void> {
  if (navigator.serviceWorker.controller) {
    return Promise.resolve();
  }

  return new Promise<void>((resolve) => {
    const timeout = setTimeout(() => {
      // Fallback: resolve anyway so the app doesn't hang
      resolve();
    }, 5000);

    navigator.serviceWorker.addEventListener(
      'controllerchange',
      () => {
        clearTimeout(timeout);
        resolve();
      },
      { once: true }
    );
  });
}

/**
 * Update the auth token stored in the Service Worker.
 */
export function updateSwToken(token: string): void {
  sendToSW({ type: 'update-token', token });
}

/**
 * Set the API base URL in the Service Worker.
 */
export function setSwApiBase(url: string): void {
  sendToSW({ type: 'set-api-base', url });
}

/**
 * Register a decrypt stream context in the Service Worker.
 * After calling this, set the media element's src to
 * `/decrypt-stream/{fileMetaIpnsName}` for transparent decryption.
 */
export function registerStream(params: {
  fileMetaIpnsName: string;
  fileKey: string;
  iv: string;
  cid: string;
  totalSize: number;
  mimeType: string;
}): void {
  sendToSW({ type: 'register-stream', ...params });
}

/**
 * Remove a decrypt stream context and its cached data from the SW.
 */
export function unregisterStream(fileMetaIpnsName: string): void {
  sendToSW({ type: 'unregister-stream', fileMetaIpnsName });
}

import { defineConfig, devices } from '@playwright/test';
import { config } from 'dotenv';
import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';

// ESM compatibility
const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// Load environment variables from .env file
config({ path: resolve(__dirname, '.env') });

// When BASE_URL points to an external environment (staging/prod), skip local webServer startup
const isExternalTarget =
  process.env.BASE_URL &&
  !process.env.BASE_URL.includes('localhost') &&
  !process.env.BASE_URL.includes('127.0.0.1');

export default defineConfig({
  testDir: './tests',

  // No global setup needed - tests handle their own authentication
  // (Removed globalSetup: './global-setup.ts')

  // Run tests sequentially (single session approach)
  fullyParallel: false,
  workers: 1,

  // Fail build on CI if tests marked as test.only
  forbidOnly: !!process.env.CI,

  // No retries - fix flakiness immediately (per CONTEXT.md)
  retries: 0,

  // Reporter for local and CI
  reporter: process.env.CI ? [['html', { open: 'never' }]] : 'list',

  use: {
    // Base URL for app under test (override with BASE_URL env var for staging)
    baseURL: process.env.BASE_URL || 'http://localhost:5173',

    // Capture artifacts on failure only
    screenshot: 'only-on-failure',
    video: 'retain-on-failure',
    trace: 'retain-on-failure',
  },

  // Projects - Chromium only (per CONTEXT.md)
  projects: [
    {
      name: 'chromium',
      use: {
        ...devices['Desktop Chrome'],
        // No storage state - tests handle their own authentication in a single session
      },
    },
  ],

  // Web server configuration - start API, web app, and mock IPNS routing service
  // Skipped when BASE_URL points to an external environment (staging/prod)
  // Note: Commands run from the workspace root (two levels up from tests/web-e2e)
  ...(isExternalTarget
    ? {}
    : {
        webServer: [
          {
            // Mock IPNS routing service - must start first as API depends on it
            // Uses MOCK_IPNS_URL env var to allow external server (e.g., Docker)
            command: 'node tools/mock-ipns-routing/dist/index.js',
            url: process.env.MOCK_IPNS_URL || 'http://localhost:3001/health',
            reuseExistingServer: true, // Always reuse if available
            timeout: 30000,
            cwd: resolve(__dirname, '../..'),
            stdout: 'pipe',
            stderr: 'pipe',
          },
          {
            command: 'pnpm --filter @cipherbox/api dev',
            url: 'http://localhost:3000/health',
            reuseExistingServer: !process.env.CI,
            timeout: 120000,
            cwd: resolve(__dirname, '../..'),
            stdout: 'pipe',
            stderr: 'pipe',
          },
          {
            command: 'pnpm --filter @cipherbox/web dev',
            url: 'http://localhost:5173',
            reuseExistingServer: !process.env.CI,
            timeout: 120000,
            cwd: resolve(__dirname, '../..'),
          },
        ],
      }),
});

/**
 * Streaming Crypto Service - Mode selection and AES-256-CTR streaming encryption
 *
 * Media files above 256KB are encrypted with AES-256-CTR using streaming 1MB chunks,
 * which keeps memory bounded regardless of file size. CTR mode produces ciphertext
 * that supports random-access decryption for streaming media playback.
 *
 * Non-media files and small media files continue using AES-256-GCM via the
 * existing file-crypto.service.ts path.
 */

import {
  generateFileKey,
  generateCtrIv,
  wrapKey,
  clearBytes,
  bytesToHex,
  AES_CTR_LENGTH,
  AES_CTR_NONCE_SIZE,
} from '@cipherbox/crypto';

import type { EncryptedFileResult } from './file-crypto.service';

/** MIME types eligible for CTR streaming encryption */
const STREAMING_MIME_TYPES = new Set([
  'video/mp4',
  'video/webm',
  'audio/mpeg',
  'audio/mp4',
  'audio/webm',
  'audio/ogg',
  'audio/aac',
]);

/** Minimum file size (bytes) to use CTR mode: 256KB */
const CTR_SIZE_THRESHOLD = 256 * 1024;

/** Chunk size for streaming encryption: 1MB */
const CHUNK_SIZE = 1024 * 1024;

