import { test, expect } from '@playwright/test';
import { createTestAccount, setupMockWallet, loginViaWallet } from '../utils/wallet-login-helpers';
import { createTestMediaFile, cleanupTestFiles } from '../utils/test-files';
import { FileListPage } from '../page-objects/file-browser/file-list.page';
import { UploadZonePage } from '../page-objects/file-browser/upload-zone.page';
import { ContextMenuPage } from '../page-objects/file-browser/context-menu.page';

test('diagnose CTR streaming pipeline', async ({ browser }) => {
  test.setTimeout(180_000);

  const account = createTestAccount();
  const context = await browser.newContext();
  const page = await context.newPage();

  // Collect console messages
  const consoleLogs: string[] = [];
  page.on('console', msg => consoleLogs.push(`[${msg.type()}] ${msg.text()}`));

  await setupMockWallet(page, account);
  const result = await loginViaWallet(page, { timeout: 90_000 });
  expect(result.outcome).toBe('success');

  const fileList = new FileListPage(page);
  const uploadZone = new UploadZonePage(page);
  const contextMenu = new ContextMenuPage(page);
  const timestamp = Date.now();
  const videoName = `diag-${timestamp}.mp4`;

  // 1. Check SW state BEFORE upload
  const swBefore = await page.evaluate(() => ({
    supported: 'serviceWorker' in navigator,
    controller: !!navigator.serviceWorker?.controller,
    controllerUrl: navigator.serviceWorker?.controller?.scriptURL || null,
  }));
  console.log('SW state before upload:', JSON.stringify(swBefore));

  // 2. Upload large video
  const file = createTestMediaFile('test-video.mp4', videoName);
  await uploadZone.uploadFile(file.path);
  await fileList.waitForItemToAppear(videoName, { timeout: 60_000 });
  console.log('Upload complete');

  // 3. Check SW state AFTER upload
  const swAfter = await page.evaluate(() => ({
    controller: !!navigator.serviceWorker?.controller,
    controllerUrl: navigator.serviceWorker?.controller?.scriptURL || null,
  }));
  console.log('SW state after upload:', JSON.stringify(swAfter));

  // 4. Open preview and check streaming state
  await fileList.rightClickItem(videoName);
  await contextMenu.waitForOpen();
  await contextMenu.clickPreview();
  await page.locator('.video-player-modal').waitFor({ state: 'visible', timeout: 30_000 });

  // Wait a bit for streaming hooks to resolve
  await page.waitForTimeout(5_000);

  // 5. Check video element state
  const videoState = await page.evaluate(() => {
    const video = document.querySelector('.video-player-modal video') as HTMLVideoElement;
    if (!video) return { found: false };
    return {
      found: true,
      src: video.src?.substring(0, 100),
      isBlobUrl: video.src?.startsWith('blob:'),
      isStreamUrl: video.src?.includes('/decrypt-stream/'),
      readyState: video.readyState,
      error: video.error?.message || null,
    };
  });
  console.log('Video element state:', JSON.stringify(videoState));

  // 6. Check if cipher badge exists
  const badgeExists = await page.locator('.video-cipher-badge').count();
  console.log('Cipher badge count:', badgeExists);

