/**
 * Streaming Crypto Service - Mode selection and AES-256-CTR streaming encryption
 *
 * Media files above 256KB are encrypted with AES-256-CTR using streaming 1MB chunks,
 * which keeps memory bounded regardless of file size. CTR mode produces ciphertext
 * that supports random-access decryption for streaming media playback.
 *
 * Non-media files and small media files continue using AES-256-GCM via the
 * existing file-crypto.service.ts path.
 */

import {
  generateFileKey,
  generateCtrIv,
  wrapKey,
  clearBytes,
  bytesToHex,
  AES_CTR_LENGTH,
  AES_CTR_NONCE_SIZE,
} from '@cipherbox/crypto';

import type { EncryptedFileResult } from './file-crypto.service';

/** MIME types eligible for CTR streaming encryption */
const STREAMING_MIME_TYPES = new Set([
  'video/mp4',
  'video/webm',
  'audio/mpeg',
  'audio/mp4',
  'audio/webm',
  'audio/ogg',
  'audio/aac',
]);

/** Minimum file size (bytes) to use CTR mode: 256KB */
const CTR_SIZE_THRESHOLD = 256 * 1024;

/** Chunk size for streaming encryption: 1MB */
const CHUNK_SIZE = 1024 * 1024;

/** AES-CTR algorithm name */
const AES_CTR_ALGORITHM = 'AES-CTR';

/**
 * Select encryption mode based on file MIME type and size.
 *
 * Returns 'CTR' for media files above 256KB (streaming media benefits from
 * random-access decryption). All other files use 'GCM' for authenticated encryption.
 *
 * @param file - File to classify
 * @returns 'CTR' for streaming media, 'GCM' for everything else
 */
export function selectEncryptionMode(file: File): 'GCM' | 'CTR' {
  console.log('[CTR-DEBUG] selectEncryptionMode:', { type: file.type, size: file.size, name: file.name, threshold: CTR_SIZE_THRESHOLD, typeMatch: STREAMING_MIME_TYPES.has(file.type) });
  if (STREAMING_MIME_TYPES.has(file.type) && file.size > CTR_SIZE_THRESHOLD) {
    return 'CTR';
  }
  return 'GCM';
}

/**
 * Encrypt a file using AES-256-CTR in streaming 1MB chunks.
 *
 * The file is read in CHUNK_SIZE slices, each encrypted with a counter
 * derived from its byte offset. Each crypto.subtle.encrypt call processes
 * at most ~1MB, but all encrypted chunks are accumulated in memory before
 * being combined into the final ciphertext buffer.
 *
 * CTR ciphertext is the same size as plaintext (no auth tag overhead).
 * Integrity is provided by IPFS content addressing.
 *
 * @param file - File to encrypt
 * @param userPublicKey - User's secp256k1 public key (65 bytes, uncompressed)
 * @returns Encrypted file data with wrapped key and IV
 */
export async function encryptFileCtr(
  file: File,
  userPublicKey: Uint8Array
): Promise<EncryptedFileResult> {
  // 1. Generate unique file key and CTR IV
  const fileKey = generateFileKey();
  const iv = generateCtrIv();

  // 2. Import CryptoKey once (not per-chunk)
  const cryptoKey = await crypto.subtle.importKey(
    'raw',
    fileKey as BufferSource,
    { name: AES_CTR_ALGORITHM },
    false,
    ['encrypt']
  );

  // 3. Stream-encrypt file in 1MB chunks
  const encryptedChunks: Uint8Array[] = [];
  let offset = 0;

  while (offset < file.size) {
    const end = Math.min(offset + CHUNK_SIZE, file.size);
    const chunk = new Uint8Array(await file.slice(offset, end).arrayBuffer());

    // Compute counter for this chunk's byte offset
    const blockOffset = Math.floor(offset / 16);
    const counter = new Uint8Array(16);
    // Copy first 8 bytes of IV (nonce)
    counter.set(iv.subarray(0, AES_CTR_NONCE_SIZE), 0);
    // Set bytes 8-15 to blockOffset as big-endian uint64
    const dv = new DataView(counter.buffer);
    dv.setBigUint64(8, BigInt(blockOffset), false);

    const encrypted = await crypto.subtle.encrypt(
      { name: AES_CTR_ALGORITHM, counter, length: AES_CTR_LENGTH },
      cryptoKey,
      chunk
    );

    encryptedChunks.push(new Uint8Array(encrypted));
    offset = end;
  }

  // 4. Combine encrypted chunks into single Uint8Array
  const totalSize = encryptedChunks.reduce((sum, c) => sum + c.length, 0);
  const ciphertext = new Uint8Array(totalSize);
  let writeOffset = 0;
  for (const chunk of encryptedChunks) {
    ciphertext.set(chunk, writeOffset);
    writeOffset += chunk.length;
  }

  // 5. Wrap file key with user's public key (ECIES)
  const wrappedKey = await wrapKey(fileKey, userPublicKey);

  // 6. Clear sensitive key from memory
  clearBytes(fileKey);

  return {
    ciphertext,
    iv: bytesToHex(iv),
    wrappedKey: bytesToHex(wrappedKey),
    originalSize: file.size,
    encryptedSize: file.size, // CTR: same size as plaintext (no auth tag)
    encryptionMode: 'CTR' as const,
  };
}

import { test, expect, Browser, BrowserContext, Page } from '@playwright/test';
import { createTestAccount, setupMockWallet, loginViaWallet } from '../utils/wallet-login-helpers';
import { createTestMediaFile, cleanupTestFiles } from '../utils/test-files';
import { deleteAccountViaPage } from '../utils/cleanup-helpers';
import { FileListPage } from '../page-objects/file-browser/file-list.page';
import { UploadZonePage } from '../page-objects/file-browser/upload-zone.page';
import { ContextMenuPage } from '../page-objects/file-browser/context-menu.page';

/**
 * AES-CTR Streaming Playback E2E Test Suite
 *
 * Verifies the streaming decryption pipeline:
 * - Large video (>256KB) triggers AES-CTR mode via service worker interception
 * - Small video (<256KB) falls back to AES-GCM blob URL playback
 * - Video player modal renders with controls and encrypted badge
 * - Decrypt progress indicator appears during initial load
 */
test.describe.serial('AES-CTR Streaming Playback', () => {
  let browser: Browser;
  let context: BrowserContext;
  let page: Page;
  let fileList: FileListPage;
  let uploadZone: UploadZonePage;
  let contextMenu: ContextMenuPage;
  const timestamp = Date.now();
  const videoName = `stream-test-${timestamp}.mp4`;
  const smallVideoName = `stream-small-${timestamp}.mp4`;

  test.setTimeout(180_000);

  test.beforeAll(async ({ browser: b }) => {
    // Extend hook timeout — match suite timeout (default 30s is too short for wallet login)
    test.setTimeout(180_000);
    browser = b;
    const account = createTestAccount();
    context = await browser.newContext();
    page = await context.newPage();
    // DEBUG: capture ALL browser console for CTR pipeline investigation
    page.on('console', (msg) => console.log(`[BROWSER:${msg.type()}]`, msg.text()));
    await setupMockWallet(page, account);
    const result = await loginViaWallet(page, { timeout: 90_000 });
    expect(result.outcome).toBe('success');
    fileList = new FileListPage(page);
    uploadZone = new UploadZonePage(page);
    contextMenu = new ContextMenuPage(page);
  });

  test.afterAll(async () => {
    cleanupTestFiles();
    if (page) await deleteAccountViaPage(page);
    if (context) await context.close();
  });

  test('upload large video file (CTR mode)', async () => {
    const file = createTestMediaFile('test-video.mp4', videoName);
    await uploadZone.uploadFile(file.path);
    await fileList.waitForItemToAppear(videoName, { timeout: 60_000 });
    expect(await fileList.isItemVisible(videoName)).toBe(true);
  });

  test('video preview opens with player controls', async () => {
    await fileList.rightClickItem(videoName);
    await contextMenu.waitForOpen();
    await contextMenu.clickPreview();

    // Wait for the video player modal to appear
    await page.locator('.video-player-modal').waitFor({ state: 'visible', timeout: 30_000 });

    // Assert video element is present inside the modal
    await expect(page.locator('.video-player-modal video')).toBeVisible({ timeout: 15_000 });

    // Close modal
    await page.keyboard.press('Escape');
    await page.locator('.video-player-modal').waitFor({ state: 'hidden', timeout: 5_000 });
  });

  test('CTR encrypted badge visible for large video', async () => {
    // Re-open preview
    await fileList.rightClickItem(videoName);
    await contextMenu.waitForOpen();
    await contextMenu.clickPreview();
    await page.locator('.video-player-modal').waitFor({ state: 'visible', timeout: 30_000 });

    // Wait for the encrypted badge indicating AES-CTR streaming mode
    await page.locator('.video-cipher-badge').waitFor({ state: 'visible', timeout: 30_000 });
    const badgeText = await page.locator('.video-cipher-badge').textContent();
    expect(badgeText?.toUpperCase()).toContain('ENCRYPTED');

    // Close modal
    await page.keyboard.press('Escape');
    await page.locator('.video-player-modal').waitFor({ state: 'hidden', timeout: 5_000 });
  });

  test('decrypt progress shows during initial load', async () => {
    // Re-open preview
    await fileList.rightClickItem(videoName);
    await contextMenu.waitForOpen();
    await contextMenu.clickPreview();
    await page.locator('.video-player-modal').waitFor({ state: 'visible', timeout: 30_000 });

    // The progress bar may appear very briefly -- use a soft assertion
    const progressFill = page.locator('.video-decrypt-progress-fill');
    const appeared = await progressFill
      .waitFor({ state: 'visible', timeout: 5_000 })
      .then(() => true)
      .catch(() => false);

    if (appeared) {
      // Verify it has a width style (indicating actual progress rendering)
      const style = await progressFill.getAttribute('style');
      expect(style).toContain('width');
    }
    // If it didn't appear, the decrypt was too fast to observe -- acceptable

    // Close modal
    await page.keyboard.press('Escape');
    await page.locator('.video-player-modal').waitFor({ state: 'hidden', timeout: 5_000 });
  });

  test('upload small video file (GCM fallback)', async () => {
    const file = createTestMediaFile('test-video-small.mp4', smallVideoName);
    await uploadZone.uploadFile(file.path);
    await fileList.waitForItemToAppear(smallVideoName, { timeout: 60_000 });
    expect(await fileList.isItemVisible(smallVideoName)).toBe(true);
  });

  test('small video plays via blob URL (no SW interception)', async () => {
    await fileList.rightClickItem(smallVideoName);
    await contextMenu.waitForOpen();
    await contextMenu.clickPreview();
    await page.locator('.video-player-modal').waitFor({ state: 'visible', timeout: 30_000 });

    // Wait for the video element to have a src attribute
    const videoEl = page.locator('.video-player-modal video');
    await expect(videoEl).toBeVisible({ timeout: 15_000 });

    // Small files use GCM decryption with blob: URL (no service worker interception)
    const src = await videoEl.getAttribute('src');
    expect(src).toBeTruthy();
    expect(src!.startsWith('blob:')).toBe(true);

    // Close modal
    await page.keyboard.press('Escape');
    await page.locator('.video-player-modal').waitFor({ state: 'hidden', timeout: 5_000 });
  });
});

